  $new=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],__DIR__.'/uploads/'.$new)){flash('No se pudo guardar el archivo.','error');header('Location: index.php?page=myfile');exit;}
  $stored=$new;$original=$f['name'];
 }
