ead"><div><h3>Cargar documento</h3><p>Formatos PDF, JPG o PNG · máximo 5 MB.</p></div></div><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="action" value="upload_document"><label>Tipo de documento<select name="type" required><?php foreach(['solicitud'=>'Solicitud','carta_compromiso'=>'Carta compromiso','carta_aceptacion'=>'Carta de aceptación','plan_trabajo'=>'Plan de trabajo','reporte_bimestral'=>'Reporte bimestral','evaluacion'=>'Evaluación','reporte_final'=>'Reporte final','carta_terminacion'=>'Carta de terminación','otro'=>'Otro'] as $k=>$v): ?><option value="<?= $k ?>"><?= $v ?></option><?php endforeach; ?></select></label><label>Archivo<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required></label><label>Folio (si aplica)<input name="folio" placeholder="Ej. SS-2026-001"></label><label>Periodo o bimestre<input name="period_label" placeholder="Ej. Bimestre 1"></label><label>Fecha del documento<input type="date" name="doc_date"></label><button class="btn primary">Cargar y validar →</button></form></section><section class="panel"><div class="panel-head"><div><h3>Mis documentos</h3><p>Estado de las entregas.</p></div></div><?php if(!$docs): ?><div class="empty">Todavía no has cargado documentos.</div><?php else: ?><div class="doc-list"><?php foreach($docs as $d): ?><div class="doc-row"><div class="file-icon">FILE</div><div class="doc-info"><b><?= h($d['original_name']) ?></b><small><?= h(str_replace('_',' ',$d['type'])) ?> · <?= h($d['created_at']) ?></small><?php if($d['validation_notes']): ?><small class="note"><?= h($d['validation_notes']) ?></small><?php endif; ?></div><?= badge($d['status']) ?><a class="btn small" href="index.php?action=download_document&id=<?= (int)$d['id'] ?>">Descargar</a><?php if(in_array($d['status'],['recibido','observado','rechazado'],true)): ?><details class="edit-document"><summary>Editar</summary><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="action" value="update_document"><input type="hidden" name="document_id" value="<?= (int)$d['id'] ?>"><label>Tipo<select name="type"><?php foreach(['solicitud'=>'Solicitud','carta_compromiso'=>'Carta compromiso','carta_aceptacion'=>'Carta de aceptación','plan_trabajo'=>'Plan de trabajo','reporte_bimestral'=>'Reporte bimestral','evaluacion'=>'Evaluación','reporte_final'=>'Reporte final','carta_terminacion'=>'Carta de terminación','otro'=>'Otro'] as $k=>$v): ?><option value="<?= $k ?>" <?= $d['type']===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label><label>Reemplazar archivo (opcional)<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png"></label><label>Folio<input name="folio" value="<?= h($d['folio']??'') ?>"></label><label>Periodo<input name="period_label" value="<?= h($d['period_label']??'') ?>"></label><label>Fecha<input type="date" name="doc_date" value="<?= h($d['doc_date']??'') ?>"></label><button class="btn primary small">Guardar cambios</button></form></details><?php endif; ?></div><?php endforeach; ?></div><?php endif; ?></section></div><section class="panel"><div class="panel-head"><div><h3>Reportes bimestrales</h3><p>Registra las actividades y horas del periodo.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="action" value="create_report"><label>Bimestre<select name="period_no"><option value="1">Bimestre 1</option><option value="2">Bimestre 2</option><option value="3">Bimestre 3</option></select></label><label>Horas del periodo<input type="number" min="1" max="500" step="0.5" name="hours" required></label><label>Fecha límite<input type="date" name="due_date"></label><label class="span-2">Actividades realizadas<textarea name="activities" rows="3" required></textarea></label><div class="form-actions"><button class="btn primary">Enviar reporte →</button></div></form><?php if($reports): ?><div class="table-wrap"><table><thead><tr><th>Periodo</th><th>Horas</th><th>Estado</th><th>Enviado</th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td>Bimestre <?= h($r['period_no']) ?></td><td><?= h($r['hours']) ?></td><td><?= badge($r['status']) ?></td><td><?= h($r['submitted_at']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
<?php if($page==='files'): require_role(['admin','supervisor']);$rows=$pdo->query('SELECT e.*,s.control_number,u.name student_name,p.name program_name FROM expedientes e JOIN students s ON s.id=e.student_id LEFT JOIN users u ON u.id=s.user_id LEFT JOIN programs p ON p.id=e.program_id ORDER BY e.updated_at DESC')->fetchAll(); ?><section class="panel"><div class="panel-head"><div><h3>Expedientes registrados</h3><p>Consulta el avance y actualiza el estado administrativo.</p></div><span class="count-pill"><?= count($rows) ?> expedientes</span></div><div class="table-wrap"><table><thead><tr><th>Estudiante</th><th>Programa</th><th>Horas</th><th>Estado</th><th>Actualizar estado</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= h($r['student_name']) ?></b><small><?= h($r['control_number']) ?></small></td><td><?= h($r['program_name']??'Sin asignar') ?></td><td><?= h($r['total_hours']) ?>/500</td><td><?= badge($r['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="action" value="update_expediente"><input type="hidden" name="expediente_id" value="<?= $r['id'] ?>"><select name="status"><?php foreach(['pre_registro','en_proceso','pendiente_revision','observado','completo','liberado','baja'] as $st): ?><option value="<?= $st ?>" <?= $st===$r['status']?'selected':'' ?>><?= ucfirst(str_replace('_',' ',$st)) ?></option><?php endforeach; ?></select><input name="notes" placeholder="Observación breve"><button class="btn small">Guardar</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if($page==='documents'): require_role(['admin','supervisor']);$rows=$pdo->query('SELECT d.*,s.control_number,u.name student_name FROM documents d JOIN expedientes e ON e.id=d.expediente_id JOIN students s ON s.id=e.student_id LEFT JOIN users u ON u.id=s.user_id ORDER BY FIELD(d.status,\'observado\',\'recibido\',\'rechazado\',\'validado\',\'aprobado\'),d.created_at DESC')->fetchAll(); ?><section class="panel"><div class="panel-head"><div><h3>Bandeja de validación</h3><p>Descarga el archivo, verifica los datos y registra el resultado. Solo el personal autorizado puede validar, observar o aprobar.</p></div><span class="count-pill"><?= count($rows) ?> documentos</span></div><?php if(!$rows): ?><div class="empty">No hay documentos cargados.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Documento</th><th>Estudiante</th><th>Folio</th><th>Estado</th><th>Revisión humana</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= h($r['original_name']) ?></b><small><?= h(str_replace('_',' ',$r['type'])) ?> · <?= h($r['created_at']) ?></small><a class="text-link" href="index.php?action=download_document&id=<?= (int)$r['id'] ?>">Descargar archivo</a></td><td><?= h($r['student_name']) ?><small><?= h($r['control_number']) ?></small></td><td><?= h($r['folio']??'—') ?></td><td><?= badge($r['status']) ?><small><?= h($r['validation_notes']??'') ?></small></td><td><form method="post" class="review-form"><input type="hidden" name="action" value="review_document"><input type="hidden" name="document_id" value="<?= $r['id'] ?>"><select name="status"><option value="validado">Validado</option><option value="observado">Observado</option><option value="rechazado">Rechazado</option><?php if($role==='admin'): ?><option value="aprobado">Aprobado oficialmente</option><?php endif; ?></select><input name="notes" placeholder="Motivo / observación" required><button class="btn small">Registrar</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
<?php if($page==='events'): require_login();$rows=$pdo->query('SELECT e.*,u.name FROM events e LEFT JOIN users u ON u.id=e.user_id ORDER BY e.created_at DESC LIMIT 100')->fetchAll(); ?><section class="panel"><div class="panel-head"><div><h3>Bitácora de movimientos</h3><p>Registro de acciones del prototipo.</p></div></div><?php if(!$rows): ?><div class="empty">No hay movimientos todavía.</div><?php else: ?><div class="activity-list"><?php foreach($rows as $r): ?><div class="activity"><div class="activity-dot"></div><div><b><?= h($r['description']) ?></b><small><?= h($r['name']??'Sistema') ?> · <?= h($r['event_type']) ?> · <?= h($r['created_at']) ?></small></div></div><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
